class GetReceivedGifts(TDObject, tag="getReceivedGifts", kw_only=True):
    """Returns gifts received by the given user or chat

    Args:
        business_connection_id: Unique identifier of business connection on behalf of which
            to send the request; for bots only
        owner_id: Identifier of the gift receiver
        collection_id: Pass collection identifier to get gifts only from the specified
            collection; pass 0 to get gifts regardless of collections
        exclude_unsaved: Pass true to exclude gifts that aren't saved to the chat's profile
            page. Always true for gifts received by other users and channel chats without
            can_post_messages administrator right
        exclude_saved: Pass true to exclude gifts that are saved to the chat's profile page.
            Always false for gifts received by other users and channel chats without
            can_post_messages administrator right
        exclude_unlimited: Pass true to exclude gifts that can be purchased unlimited number
            of times
        exclude_upgradable: Pass true to exclude gifts that can be purchased limited number
            of times and can be upgraded
        exclude_non_upgradable: Pass true to exclude gifts that can be purchased limited
            number of times and can't be upgraded
        exclude_upgraded: Pass true to exclude upgraded gifts
        exclude_without_colors: Pass true to exclude gifts that can't be used in
            setUpgradedGiftColors
        exclude_hosted: Pass true to exclude gifts that are just hosted and are not owned by
            the owner
        sort_by_price: Pass true to sort results by gift price instead of send date
        offset: Offset of the first entry to return as received from the previous request;
            use empty string to get the first chunk of results
        limit: The maximum number of gifts to be returned; must be positive and can't be
            greater than 100. For optimal performance, the number of returned objects is
            chosen by TDLib and can be smaller than the specified limit
    """

    business_connection_id: str = ""
    owner_id: MessageSender
    collection_id: int = 0
    exclude_unsaved: bool = False
    exclude_saved: bool = False
    exclude_unlimited: bool = False
    exclude_upgradable: bool = False
    exclude_non_upgradable: bool = False
    exclude_upgraded: bool = False
    exclude_without_colors: bool = False
    exclude_hosted: bool = False
    sort_by_price: bool = False
    offset: str = ""
    limit: int = 0


